return ['domain'=>'zinn-chat','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'zinn-chat','pot-creation-date'=>'2026-10-05T16:57:09+00:00','po-revision-date'=>'2026-10-05T16:57:09+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Chat'=>'Zinn® Chat','https://zinndigital.com/wordpress-plugins/zinn-chat'=>'https://zinndigital.com/wordpress-plugins/zinn-chat','A complete help desk and AI assistant that runs on your own WordPress: an AI that answers from your own pages with links, live chat, and support tickets in wp-admin, on a submit-a-ticket page and in the WooCommerce account area. Under 10 KB on the page and no requests at all until a visitor opens it.'=>'Kompletní help desk a AI asistent, který běží na vašem vlastním WordPress: AI, která odpovídá z vašich vlastních stránek pomocí odkazů, živého chatu a ticketů podpory ve wp-admin, na stránce pro odeslání ticketu a v sekci účtu WooCommerce. Na stránce zabírá méně než 10 KB a nevygeneruje žádné požadavky, dokud jej návštěvník neotevře.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Inbox'=>'Doručená pošta','Tickets'=>'Požadavky','Assistant'=>'Asistent','Settings'=>'Nastavení','Setup'=>'Nastavení','Zinn® Chat could not create its database tables:'=>'Zinn® Chat nemohl vytvořit své databázové tabulky:','The AI assistant could not answer a visitor:'=>'AI asistent nedokázal odpovědět návštěvníkovi:','Fix it'=>'Opravit','Loading…'=>'Načítání…','This screen needs JavaScript.'=>'Tato obrazovka vyžaduje JavaScript.','Chat'=>'Chat','AI assistant'=>'Asistent AI','Tickets and email'=>'Ticketový systém a e-mail','Site index'=>'Index stránek','Privacy and spam'=>'Soukromí a spam','Connect to Zinn Digital®'=>'Připojit k Zinn Digital®','AI agents (MCP)'=>'AI agenté (MCP)','Show the chat on the site'=>'Zobrazit chat na webu','Nothing appears on the site, and nothing is loaded, until this is ticked.'=>'Dokud toto nebude zaškrtnuto, na webu se nic nezobrazí ani nenačte.','Chat title'=>'Název chatu','Greeting'=>'Uvítání','The first thing a visitor sees.'=>'První věc, kterou návštěvník uvidí.','Greeting when nobody can answer'=>'Uvítání, když nikdo nemůže odpovědět','Colour'=>'Barva','Text colour on the colour'=>'Barva textu v barvě','Position'=>'Pozice','Bottom, end side (right in left-to-right languages)'=>'Spodní, koncová strana (vpravo v jazycích psaných zleva doprava)','Bottom, start side'=>'Dole, začáteční strana','Offer "Talk to a person"'=>'Nabídka „Mluvit s osobou“','Shown while somebody has the Inbox open and is not set to away.'=>'Zobrazí se, když má někdo otevřenou doručenou poštu a není nastaven jako „pryč“.','Hide the chat from your support team while they are signed in'=>'Skrýt chat pro váš tým podpory, když jsou přihlášeni','Show "Powered by Zinn® Chat" under the chat'=>'Zobrazit pod čarou chatu nápis „Powered by Zinn® Chat“','Optional. Off unless you turn it on.'=>'Volitelné. Vypnuto, dokud to nezapnete.','Your chat texts in other languages'=>'Vaše texty chatu v jiných jazycích','With Tranzly, WPML or Polylang you do not need this: your texts are listed there with your other site texts (Tranzly: Menus and shared text, then "Site title, tagline and widgets"; WPML: String Translation, in the Zinn® Chat context; Polylang: Strings translations, in the Zinn® Chat group), and visitors see them in their own language. Without a multilingual plugin, write your own version for each language here, with its code (for example de, ar or pt_BR). A field left empty shows your main text.'=>'S nástroji Tranzly, WPML nebo Polylang toto nepotřebujete: Vaše texty jsou tam uvedeny společně s ostatními texty Vašeho webu (Tranzly: Menus and shared text, poté „Site title, tagline and widgets“; WPML: String Translation, v kontextu Zinn® Chat; Polylang: Strings translations, ve skupině Zinn® Chat) a návštěvníci je vidí ve svém vlastním jazyce. Bez vícejazyčného pluginu zde napište svou vlastní verzi pro každý jazyk s jeho kódem (například de, ar nebo pt_BR). Pole ponechané prázdné zobrazí Váš hlavní text.','Let the AI assistant answer visitors'=>'Nechte AI asistenta odpovídat návštěvníkům','Assistant name'=>'Jméno asistenta','Extra instructions for the assistant'=>'Další pokyny pro asistenta','For example: "Always mention our 30-day returns." They cannot override the safety rules.'=>'Například: „Vždy zmiňujte naše 30denní vrácení peněz.“ Nemohou přepsat bezpečnostní pravidla.','Answer language'=>'Jazyk odpovědi','"auto" answers in the visitor\'s own language; or a locale such as en_GB or de_DE to always answer in one language.'=>'„auto“ odpovídá v jazyce návštěvníka; případně zadejte národní prostředí jako en_GB nebo de_DE pro odpovědi v jediném jazyce.','Minimum relevance'=>'Minimální relevance','Passages scoring below this (0 to 0.95) are not used, and the assistant says it does not know. Check scores in the test console.'=>'Pasáže dosahující skóre pod touto hodnotou (0 až 0,95) se nepoužívají a asistent uvede, že to neví. Skóre můžete zkontrolovat v testovací konzoli.','Offer a person after this many unanswered questions'=>'Nabídnout osobu po tolika nezodpovězených otázkách','Longest answer (tokens)'=>'Nejdelší odpověd\' (tokenů)','Accept support tickets'=>'Přijímat tickety podpory','Support page'=>'Stránka podpory','The page with the [zinn_chat_support] shortcode or the Support page block. Ticket links in emails open this page.'=>'Stránka s krátkým kódem [zinn_chat_support] nebo blokem stránky Podpora. Odkazy na tikety v e-trzích otevírají tuto stránku.','Send team alerts to'=>'Odesílat týmová upozornění na adresu','One or more email addresses, separated by commas. Empty: the site admin email.'=>'Jedna nebo více e-mailových adres oddělených čárkami. Prázdné: e-mail správce webu.','Sender name on emails'=>'Jméno odesílatele v e-mailech','Email the team when a visitor waits for a person longer than (minutes)'=>'Odeslat e-mail týmu, když návštěvník čeká na osobu déle než (minut)','Private ticket links work for (days after the last message)'=>'Odkazy na soukromé tikety fungují po dobu (dnů od poslední zprávy)','After that the page offers to email a new link.'=>'Poté stránka nabídne odeslání nového odkazu e-mailem.','Add a Support tab to the WooCommerce account area'=>'Přidat kartu Podpora do sekce účtu WooCommerce','Let the assistant tell signed-in customers about their own orders'=>'Umožněte asistenci sdělovat přihlášeným zákazníkům informace o jejich vlastních objednávkách','Answers "where is my order?" from the order status and tracking.'=>'Odpovídá na otázku „kde je moje objednávka?“ ze stavu objednávky a sledování zásilky.','Content the assistant reads'=>'Obsah, který asistent čte','None ticked means every public type.'=>'Žádná zaškrtnutá položka znamená všechny veřejné typy.','WooCommerce products, prices, stock, shipping and payment methods'=>'Produkty, ceny, skladové zásoby, doprava a platební metody WooCommerce','Forums (bbPress, BuddyBoss, wpForo)'=>'Fóra (bbPress, BuddyBoss, wpForo)','Read pages as visitors see them when a page builder\'s content cannot be read directly'=>'Čtení stránek tak, jak je vidí návštěvníci, když obsah tvůrce stránek nelze číst přímo','Fetches the page from your own site in the background.'=>'Načte stránku z vašeho vlastního webu na pozadí.','Never read these posts or pages (IDs)'=>'Nikdy nečíst tyto příspěvky nebo stránky (ID)','Comma-separated.'=>'Oddělené čárkami.','Ask visitors to agree before a chat or ticket'=>'Požádejte návštěvníky o souhlas před zahájením chatu nebo vytvořením tiketu','Agreement text'=>'Text smlouvy','Privacy policy link'=>'Odkaz na zásady ochrany osobních údajů','Empty: the site\'s privacy policy page.'=>'Prázdné: stránka zásad ochrany osobních údajů webu.','Delete finished chats and tickets after (days)'=>'Odstranit dokončené chaty a tikety po (dnech)','0 keeps them.'=>'0 si jich ponechá.','Store visitors\' IP addresses'=>'Ukládat IP adresy návštěvníků','Off: only a coded form is kept, enough for spam limits.'=>'Vypnuto: uchovává se pouze kódovaná podoba, která stačí pro limity spamu.','Messages per visitor per hour'=>'Zpráv za návštěvníka za hodinu','Chats per visitor per day'=>'Chatů na návštěvníka a den','Tickets per visitor per day'=>'Požadavky na návštěvníka za den','Longest chat message (characters)'=>'Nejdelší zpráva chatu (znaky)','Block list'=>'Seznam blokovaných','One per line: an IP address, an email address, @domain.com, or a word.'=>'Jedna na řádek: IP adresa, e-mailová adresa, @domain.com nebo slovo.','Where chats are answered'=>'Kde jsou chaty zodpovídány','"This site" keeps everything in this site\'s database and uses your own AI key. "Zinn Digital®" uses the hosted inbox in the Zinn® app (for Zinn® hosting customers).'=>'„Tento web“ uchovává vše v databázi tohoto webu a používá váš vlastní klíč umělé inteligence. „Zinn Digital®“ využívá hostovanou schránku v aplikaci Zinn® (pro zákazníky hostingu Zinn®).','This site (recommended)'=>'Tento web (doporučeno)','Zinn Digital® app'=>'Aplikace Zinn Digital®','Zinn® widget key'=>'Klíč widgetu Zinn®','From the Zinn® app: Live chat, then your widget. Starts with zc_.'=>'Z aplikace Zinn®: Živý chat a poté váš widget. Začíná na zc_.','Allow AI agents (MCP)'=>'Povolit agenty AI (MCP)','Off: the tools below and their REST routes are not registered at all.'=>'Vypnuto: nástroje níže a jejich REST trasy nejsou vůbec registrovány.','Zinn® Chat settings'=>'Nastavení Zinn® Chat','Settings saved.'=>'Nastavení bylo uloženo.','The assistant uses your own AI key.'=>'Asistent používá váš vlastní klíč k umělé inteligenci.','AI providers and models'=>'Poskytovatelé a modely AI','— None —'=>'— Žádné —','Saved — leave empty to keep'=>'Uloženo – ponechte prázdné pro zachování','Remove the saved key'=>'Odstranit uložený klíč','Add a language'=>'Přidat jazyk','Language code'=>'Kód jazyka','You are not allowed to change these settings.'=>'Tyto nastavení nemůžete změnit.','Turn the chat on'=>'Zapnout chat','The chat is showing on your site.'=>'Chat se zobrazuje na vašem webu.','Nothing is shown or loaded on your site until you turn it on.'=>'Na vašem webu se nic nezobrazuje ani nenačítá, dokud ho nezapnete.','Turn off'=>'Vypnout','Turn on'=>'Zapnout','Connect your AI provider'=>'Připojte poskytovatele umělé inteligence','Connected. Site search uses %1$s (%2$s).'=>'Připojeno. Vyhledávání na webu používá %1$s (%2$s).','Connected. Your provider cannot build a meaning-based index, so the assistant uses keyword search. Add a Google Gemini, OpenAI, Mistral or OpenRouter key for better answers.'=>'Připojeno. Váš poskytovatel nemůže vytvořit index založený na významu, takže asistent používá vyhledávání podle klíčových slov. Chcete-li dosáhnout lepších výsledků, přidejte klíč Google Gemini, OpenAI, Mistral nebo OpenRouter.','Add a key for Google Gemini, OpenAI, Anthropic Claude, Mistral, OpenRouter or any OpenAI-compatible service. The newest model is chosen for you; you can change it.'=>'Přidejte klíč pro Google Gemini, OpenAI, Anthropic Claude, Mistral, OpenRouter nebo jakoukoli službu kompatibilní s OpenAI. Nejnovější model se vybere za vás; můžete jej změnit.','AI providers'=>'Poskytovatelé AI','Let the assistant read your site'=>'Nechte asistenta přečíst vaše stránky','%1$d pages read, %2$d waiting, %3$d passages. New and edited content is picked up automatically.'=>'%1$d přečtených stránek, %2$d čeká, %3$d pasáží. Nový a upravený obsah se načítá automaticky.','Read the whole site now'=>'Přečíst celý web nyní','Create your support page'=>'Vytvořte si stránku podpory','Visitors submit tickets there, and ticket emails link to it.'=>'Návštěvníci zde odesílají tikety a e-maily tiketů na něj odkazují.','A page with the ticket form, where customers also follow their requests.'=>'Stránka s formulářem tiketu, kde zákazníci také sledují své požadavky.','View'=>'Zobrazit','Create the support page'=>'Vytvořit stránku podpory','Add "Submit a ticket" and "Chat with us" to a menu'=>'Přidat do nabídky položky „Odeslat tiket“ a „Chatovat s námi“','Appearance, Menus: use the Zinn® Chat box. Or add the Zinn® Chat blocks to any page, in any page builder.'=>'Vzhled, Menu: použijte pole Zinn® Chat. Nebo přidejte bloky Zinn® Chat na libovolnou stránku v libovolném nástroji pro tvorbu stránek.','Menus'=>'Nabídky','WooCommerce account area'=>'Zákaznická zóna WooCommerce','Customers see their tickets under Support in My Account, and the assistant can tell them where their order is.'=>'Zákazníci vidí své tikety v části Podpora v Mém účtu a asistent jim může říct, kde se nachází jejich objednávka.','Test the assistant'=>'Vyzkoušet asistenta','Ask it questions and see exactly which pages it answered from, including out-of-date ones.'=>'Položte mu otázky a podívejte se přesně, ze kterých stránek odpovídalo, včetně těch zastaralých.','Open the test console'=>'Otevřít testovací konzoli','Answer live chats'=>'Odpovídat na živé chaty','Visitors can ask for a person while you have the Inbox open. It works on a phone too.'=>'Když máte otevřenou Doručenou poštu, návštěvníci mohou požádat o živého operátora. Funguje to i v telefonu.','Open the Inbox'=>'Otevřít doručenou poštu','Set up Zinn® Chat'=>'Nastavit Zinn® Chat','This site is connected to the Zinn Digital® app: chats are answered there. To run the help desk on this site instead, choose "This site" under Settings, Connect to Zinn Digital®.'=>'Tento web je připojen k aplikaci Zinn Digital®: chaty se zodpovídají tam. Pokud chcete na tomto webu místo toho provozovat oddělení podpory, zvolte v části Nastavení možnost „Tento web“, Připojit k Zinn Digital®.','You are not allowed to do that.'=>'Na to nemáte oprávnění.','Unlimited agents, with a Support agent role that sees only chats and tickets'=>'Neomezený počet agentů s rolí agenta podpory, která vidí pouze chaty a tikety','Reply to tickets by email'=>'Odpovídat na tikety e-mailem','Knowledge base: articles, categories, search, and a KB section in the chat'=>'Znalostní báze: články, kategorie, vyhledávání a sekce znalostní báze v chatu','Saved replies, business hours, priorities and SLAs'=>'Uložené odpovědi, pracovní doba, priority a SLA','Suggested replies, thread summaries and auto-tagging by AI'=>'Navrhované odpovědi, shrnutí vláken a automatické štítkování pomocí AI','Knowledge-gap report: the questions your site could not answer'=>'Zpráva o mezerách ve znalostech: otázky, na které váš web nedokázal odpovědět','Push notifications and an installable agent app for your phone'=>'Push notifikace a instalovatelná aplikace agenta pro váš telefon','Proactive messages, reports, webhooks, Slack and Telegram alerts'=>'Proaktivní zprávy, reporty, webhooky a upozornění pro Slack a Telegram','Zinn® Chat Pro'=>'Zinn® Chat Pro','From $%1$d a month or $%2$d a year for one site.'=>'Od $%1$d měsíčně nebo $%2$d ročně za jeden web.','Try Pro free for 14 days'=>'Vyzkoušejte verzi Pro na 14 dní zdarma','See plans'=>'Zobrazit plány','No card needed for the trial.'=>'Pro zkušební verzi není potřeba karta.','The makers of ChatGPT. A good all-rounder.'=>'Tvůrci ChatGPT. Dobrý všestranný nástroj.','The makers of Claude. Strong at writing and careful reasoning.'=>'Tvůrci systému Claude. Silní v psaní a pečlivém uvažování.','Google\'s Gemini models. Fast and inexpensive.'=>'Modely Gemini od společnosti Google. Rychlé a cenově dostupné.','A European AI company with fast, inexpensive models.'=>'Evropská společnost zabývající se umělou inteligencí s rychlými a cenově dostupnými modely.','Low-cost models that are good at writing and code.'=>'Nízkonákladové modely, které jsou dobré v psaní a kódování.','One key for models from many different providers.'=>'Jedno klíčové slovo pro modely od mnoha různých poskytovatelů.','Any service that works like OpenAI\'s API, including a model running on your own computer or server.'=>'Jakákoliv služba, která funguje jako API OpenAI, včetně modelu spuštěného ve vašem vlastním počítači nebo serveru.','General (used when nothing more specific is set)'=>'Obecné (použije se, není-li nastaveno nic specifičtějšího)','Writing and rewriting'=>'Zápis a přepis','Translation'=>'Překlad','Code and CSS'=>'Kód a CSS','Sorry, you are not allowed to access this page.'=>'Litujeme, nemáte oprávnění k přístupu na tuto stránku.','These settings are shared by every plugin that uses them: %s.'=>'Tato nastavení sdílí každý plugin, který je používá: %s.','Your keys are encrypted in this site\'s database and are only ever sent to the provider you chose — never to us.'=>'Vaše klíče jsou zašifrovány v databázi tohoto webu a jsou odesílány pouze vámi zvolenému poskytovateli – nám nikdy.','Step 1 of 2: choose an AI provider'=>'Krok 1 ze 2: vyberte poskytovatele umělé inteligence','You bring your own key, so you pay the provider directly for what you use. Not sure? Any of these works well; you can add more later.'=>'Přinášíte si vlastní klíč, takže za to, co spotřebujete, platíte přímo poskytovateli. Nejste si jisti? Kterákoli z těchto možností funguje dobře; další můžete přidat později.','Next'=>'Další','Step 2 of 2: connect %s'=>'Krok 2 z 2: připojte %s','Enter the address of your OpenAI-compatible service, ending in /v1. A key is only needed if the service asks for one.'=>'Zadejte adresu své služby kompatibilní s OpenAI, končící na /v1. Klíč je vyžadován pouze v případě, že si jej služba vyžádá.','Open %s and sign in (or create a free account).'=>'Otevřete %s a přihlaste se (nebo si vytvořte bezplatný účet).','the %s API keys page'=>'stránka API klíčů %s','Create a new key and copy it.'=>'Vytvořte nový klíč a zkopírujte jej.','Paste it below and press "Save and test". We send one tiny request to check it works.'=>'Vložte ho níže a stiskněte „Uložit a otestovat“. Odešleme jeden malý požadavek, abychom ověřili, že to funguje.','Most providers need a little credit on the account before a key works: %s.'=>'Většina poskytovatelů vyžaduje na účtu určitý kredit, než začne klíč fungovat: %s.','add credit'=>'přidat kredit','← Choose a different provider'=>'← Zvolit jiného poskytovatele','Address'=>'Adresa','Saved key ends in …%s — paste a new one to replace it'=>'Uložený klíč končí na …%s – vložte nový pro jeho nahrazení','Key (optional)'=>'Klíč (volitelné)','API key'=>'API klíč','Save and test'=>'Uložit a otestovat','Providers'=>'Poskytovatelé','Provider'=>'Poskytovatel','Status'=>'Stav','Key'=>'Klíč','Get a key'=>'Získat klíč','Test'=>'Test','Remove'=>'Odstranit','Saved by a newer plugin version: update this plugin, or enter the key again.'=>'Uloženo novější verzí pluginu: aktualizujte tento plugin nebo zadejte klíč znovu.','The saved key can no longer be opened (the site\'s security keys changed). Enter it again.'=>'Uložený klíč již nelze otevřít (bezpečnostní klíče webu se změněny). Zadejte jej znovu.','Not connected'=>'Nepřipojeno','Connected — last test passed %s'=>'Připojeno – poslední test úspěšný %s','Last test failed: %s'=>'Poslední test selhal: %s','Connected — not tested yet'=>'Připojeno – dosud netestováno','Which model to use'=>'Který model použít','★ marks our recommendation for that task. The list includes every model your key can use, read live from the provider.'=>'★ označuje naše doporučení pro daný úkol. Seznam obsahuje každý model, který váš klíč může používat, načtený živě od poskytovatele.','— Recommended for the provider —'=>'— Doporučeno pro poskytovatele —','Save models'=>'Uložit modely','Refresh the model lists from the providers'=>'Aktualizovat seznamy modelů od poskytovatelů','Images'=>'Obrázky','Connect OpenAI or Google Gemini to make images.'=>'Připojte OpenAI nebo Google Gemini pro vytváření obrázků.','— The newest image model of the first connected provider —'=>'— Nejnovější model obrázků prvního připojeného poskytovatele —','Site search (embeddings)'=>'Vyhledávání na webu (vložení)','Connect Google Gemini, OpenAI, Mistral or OpenRouter to build a search index of your site.'=>'Připojte Google Gemini, OpenAI, Mistral nebo OpenRouter a vytvořte vyhledávací index svého webu.','— The newest embedding model of the first connected provider —'=>'— Nejnovější model pro vkládání od prvního připojeného poskytovatele —','Changing this rebuilds the search index of every plugin that uses it.'=>'Změna tohoto nastavení znovu sestaví index vyhledávání u každého pluginu, který jej používá.','best quality'=>'nejlepší kvalita','lowest cost'=>'nejnižší cena','fastest'=>'nejrychlejší','Add a model yourself'=>'Přidat vlastní model','A model came out today? Paste its exact name to use it straight away.'=>'Vyšel dnes nový model? Vložte jeho přesný název a můžete ho ihned začít používat.','Model name'=>'Název modelu','Add model'=>'Přidat model','Recommended models list'=>'Seznam doporučených modelů','The recommended models list could not be verified, so no recommendations are shown. Reinstall the plugin, or turn on daily updates below.'=>'Seznam doporučených modelů nelze ověřit, proto se nezobrazují žádná doporučení. Přeinstalujte plugin nebo níže zapněte každodenní aktualizace.','The list in use was published on %s. Each plugin update brings a fresh one.'=>'Použitý seznam byl publikován %s. Každá aktualizace pluginu přináší nový.','Also check Zinn Digital® once a day for an updated list.'=>'Pro zajištění aktuálního seznamu kontrolujte Zinn Digital® také jednou denně.','Only a plain download request is sent: no key, no site address, nothing about your content. The list is signed, and a list that fails the signature check is ignored.'=>'Odesílá se pouze prostý požadavek na stažení: žádný klíč, žádná adresa webu, nic o vašem obsahu. Seznam je podepsaný a seznam, který neprojde kontrolou podpisu, je ignorován.','Last checked %1$s: %2$s.'=>'Naposledy zkontrolováno %1$s: %2$s.','Save, and check now if turned on'=>'Uložit a ihned zkontrolovat, pokud je zapnuto','a newer list was installed'=>'byl nainstalován novější seznam','already up to date'=>'již aktuální','the download failed the signature check and was ignored'=>'stažení selhalo při kontrole podpisu a bylo ignorováno','Zinn Digital® could not be reached; the current list stays in use'=>'Zinn Digital® nebylo možné kontaktovat; aktuální seznam zůstává v platnosti','turned off'=>'vypnuto','Open'=>'Otevřít','Check their status page'=>'Zkontrolujte jejich stavovou stránku','Open your billing page'=>'Otevřete svou stránku fakturace','Open your API keys page'=>'Otevřete stránku s klíči API','Open the AI settings'=>'Otevřít nastavení AI','Sorry, you are not allowed to do that.'=>'Litujeme, k této akci nemáte oprávnění.','Unknown provider.'=>'Neznámý poskytovatel.','Enter the address of your service, for example http://localhost:11434/v1.'=>'Zadejte adresu své služby, například http://localhost:11434/v1.','That does not look like an API key. Copy it again, without spaces.'=>'To nevypadá jako klíč API. Zkopírujte ho znovu, bez mezer.','Paste your API key first.'=>'Nejprve vložte svůj klíč API.','Key removed.'=>'Klíč byl odstraněn.','Models saved.'=>'Modely byly uloženy.','Enter the model\'s exact name, for example as the provider\'s documentation writes it.'=>'Zadejte přesný název modelu, například tak, jak je uveden v dokumentaci poskytovatele.','Added %s. Choose it under "Which model to use".'=>'Přidáno %s. Vyberte jej v části „Which model to use“.','Model removed.'=>'Model byl odstraněn.','Daily updates are off. The list that came with the plugin is used.'=>'Denní aktualizace jsou vypnuté. Používá se seznam, který byl dodán s pluginem.','Checked: %s.'=>'Zaškrtnuto: %s.','Model lists refreshed.'=>'Seznamy modelů byly aktualizovány.','Your AI key was saved by a newer version of one of your plugins. Update this plugin, or enter the key again in the AI settings.'=>'Váš klíč AI byl uložen novější verzí jednoho z vašich pluginů. Aktualizujte tento plugin nebo zadejte klíč znovu v nastavení AI.','Your saved AI key can no longer be opened (the site\'s security keys changed). Enter it again in the AI settings.'=>'Váš uložený klíč AI již nelze otevřít (bezpečnostní klíče webu se změnily). Zadejte jej znovu v nastavení AI.','AI is not set up yet. Add a key for an AI provider in the AI settings.'=>'Umělá inteligence ještě není nastavená. Přidejte klíč pro poskytovatele AI v nastavení AI.','No model is chosen for this task. Pick one in the AI settings.'=>'Pro tuto úlohu není vybrán žádný model. Zvolte jeden v nastavení AI.','That AI provider is not supported by this version of the plugin.'=>'Tento poskytovatel umělé inteligence není touto verzí modulu podporován.','No AI provider that can make images is connected. Add an OpenAI or Google Gemini key in the AI settings.'=>'Není připojen žádný poskytovatel umělé inteligence, který dokáže vytvářet obrázky. Přidejte klíč OpenAI nebo Google Gemini v nastavení umělé inteligence.','This AI provider cannot make images. Choose OpenAI or Google Gemini for images in the AI settings.'=>'Tento poskytovatel umělé inteligence neumí vytvářet obrázky. V nastavení umělé inteligence zvolte pro obrázky OpenAI nebo Google Gemini.','Your AI key cannot use any image model. Check the key\'s permissions with the provider, or choose another provider for images.'=>'Váš AI klíč nemůže používat žádný model pro tvorbu obrázků. Zkontrolujte oprávnění klíče u poskytovatele nebo pro obrázky vyberte jiného poskytovatele.','No connected AI provider can build a search index. Add a Google Gemini, OpenAI, Mistral or OpenRouter key in the AI settings.'=>'Žádný připojený poskytovatel AI nemůže vytvořit vyhledávací index. Přidejte klíč Google Gemini, OpenAI, Mistral nebo OpenRouter v nastavení AI.','Your AI key cannot use any embedding model. Check the key\'s permissions with the provider, or choose another provider for site search.'=>'Váš klíč AI nemůže používat žádný model pro vkládání. Zkontrolujte oprávnění klíče u poskytovatele nebo pro vyhledávání na webu vyberte jiného poskytovatele.','This AI provider cannot build a search index. Connect Google Gemini, OpenAI, Mistral or a compatible service for site search.'=>'Tento poskytovatel AI nemůže vytvořit vyhledávací index. Pro vyhledávání na webu připojte službu Google Gemini, OpenAI, Mistral nebo kompatibilní službu.','This site could not reach your AI service. Check that it is running and that its address is reachable from your web server (a service on your own computer is not reachable from a hosted site).'=>'Tento web nemohl navázat spojení s vaší službou AI. Zkontrolujte, zda je spuštěna a zda je její adresa dostupná z vašeho webového serveru (služba běžící na vašem vlastním počítači není z hostovaného webu dostupná).','This site could not reach %s. Check their status page; if they are up, your host may be blocking outgoing connections, or the address is wrong.'=>'Tento web se nemohl připojit k serveru %s. Zkontrolujte jeho stavovou stránku; pokud funguje, váš hostitel možná blokuje odchozí připojení nebo je adresa nesprávná.','%s says your account has no credit or quota left. Add credit or raise your limit in your account with them, then try again.'=>'%s uvádí, že vašemu účtu došel kredit nebo kvóta. Přidejte kredit nebo zvyšte svůj limit v příslušném účtu a zkuste to znovu.','%s did not accept your key. It may be mistyped, revoked or expired. Create a new key and paste it here.'=>'%s nepřijal váš klíč. Může být zapsán chybně, odvolán nebo vypršel jeho platnost. Vytvořte nový klíč a vložte jej sem.','%s refused this request for your key. The key may not have access to this model or feature, or your account needs verifying.'=>'%s tuto žádost o váš klíč odmítl(a). Klíč nemusí mít k tomuto modelu nebo funkci přístup, případně je nutné ověřit váš účet.','The model "%1$s" is not available from %2$s for your key. Choose another model in the AI settings.'=>'Model „%1$s“ není od %2$s pro váš klíč k dispozici. Vyberte jiný model v nastavení umělé inteligence.','Your %2$s plan does not include the model "%1$s". Choose another model in the AI settings, or upgrade your plan with them.'=>'Váš plán %2$s nezahrnuje model „%1$s“. Zvolte jiný model v nastavení AI nebo si upgradujte svůj plán.','%s is limiting how fast your key can send requests. Wait a minute and try again, or raise your rate limit with them.'=>'%s omezuje rychlost, s jakou může váš klíč odesílat požadavky. Počkejte minutu a zkuste to znovu, nebo u nich zvyšte svůj limit rychlosti.','%s is having problems right now (an outage or overload on their side). Nothing is wrong with your settings. Try again shortly.'=>'%s má nyní problémy (výpadek nebo přetížení na jejich straně). S vaším nastavením není nic v nepořádku. Zkuste to za chvíli znovu.','The AI request failed for a reason we could not identify. Try again; if it keeps happening, contact support with the details below.'=>'Požadavek na AI selhal z nezjištěného důvodu. Zkuste to znovu; pokud to bude pokračovat, kontaktujte podporu s níže uvedenými podrobnostmi.','The AI provider answered in a form this plugin could not read. Try again; if it keeps happening, choose another model or contact support.'=>'Poskytovatel umělé inteligence odpověděl ve formátu, kterému tento plugin nedokáže porozumět. Zkuste to znovu; pokud problém přetrvá, vyberte jiný model nebo kontaktujte podporu.','Custom (OpenAI-compatible)'=>'Vlastní (kompatibilní s OpenAI)','Save a key for this provider first.'=>'Nejprve uložte klíč pro tohoto poskytovatele.','Your key works, but the provider lists no text model for it. Add a model yourself below.'=>'Váš klíč funguje, ale poskytovatel pro něj neuvádí žádný textový model. Přidejte model sami níže.','Connected. %1$s answered using %2$s. Your AI features are ready to use.'=>'Připojeno. Uživatel %1$s odpověděl pomocí nástroje %2$s. Vaše funkce s umělou inteligencí jsou připraveny k použití.','Your user role is not allowed to use AI on this site. Ask an administrator.'=>'Vaše uživatelská role nemá na tomto webu povoleno používat umělou inteligenci. Požádejte administrátora.','This site has reached its monthly AI spending limit. An administrator can raise it in the AI settings.'=>'Tento web dosáhl svého měsíčního limitu útraty za umělou inteligenci. Správce ho může zvýšit v nastavení umělé inteligence.','This site has reached its monthly limit of AI requests. An administrator can raise it in the AI settings.'=>'Tento web dosáhl svého měsíčního limitu požadavků na umělou inteligenci. Správce ho může zvýšit v nastavení umělé inteligence.','Usage and cost'=>'Využití a náklady','The log, limits and role permissions apply to AI used through: %s.'=>'Protokol, limity a oprávnění rolí platí pro AI používanou prostřednictvím: %s.','Costs are approximate, worked out from published prices; a model with no known price counts as zero.'=>'Náklady jsou přibližné, vypočítané ze zveřejněných cen; model bez známé ceny se počítá jako nula.','This month: %1$s requests, about %2$s.'=>'Tento měsíc: %1$s požadavků, přibližně %2$s.','When'=>'Kdy','Who'=>'Kdo','Used for'=>'Používá se pro','Model'=>'Model','Tokens in / out'=>'Tokeny vstup / výstup','About'=>'O aplikaci','Result'=>'Výsledek','No AI requests have been made yet.'=>'Zatím nebyly učiněny žádné požadavky na AI.','Done'=>'Hotovo','Limits and permissions'=>'Limity a oprávnění','Monthly spending limit (US dollars)'=>'Měsíční limit útrat (US dolarů)','Leave empty for no limit. AI stops for the rest of the month once the approximate cost reaches it.'=>'Ponechte prázdné pro neomezeno. Umělá inteligence se zastaví po zbytek měsíce, jakmile odhadované náklady dosáhnou této hodnoty.','Monthly request limit'=>'Měsíční limit požadavků','Leave empty for no limit.'=>'Pro bez limitu ponechte prázdné.','Who may use AI'=>'Kdo může používat AI','Tick none to let everyone who can use the plugin\'s features use AI. Administrators can always use it.'=>'Zaškrtněte prázdné, chcete-li povolit používání umělé inteligence všem, kdo mohou využívat funkce pluginu. Správci ji mohou používat vždy.','Save limits and permissions'=>'Uložit limity a oprávnění','Limits and permissions saved.'=>'Limity a oprávnění byly uloženy.','Content'=>'Obsah','Not found.'=>'Nenalezeno.','%s joined the chat.'=>'%s se připojil(a) do chatu.','Type a reply first.'=>'Nejprve napište odpověď.','The chat has ended. Thank you for contacting us.'=>'Chat skončil. Děkujeme, že jste nás kontaktovali.','You are chatting with the assistant again.'=>'Opět si povídáte s asistentem.','This conversation is now ticket #%d. We will reply by email.'=>'Tato konverzace je nyní ticketem č. %d. Odpovíme vám e-mailem.','Type a question first.'=>'Nejprve zadejte otázku.','The whole site is being read again in the background.'=>'Celý web se znovu načítá na pozadí.','Meanings are being rebuilt in the background.'=>'Významy se znovu vytvářejí na pozadí.','Submit a ticket form'=>'Odeslat formulář tiketu','Heading'=>'Nadpis','Default subject'=>'Výchozí předmět','Button text'=>'Text tlačítka','Show the subject field (yes or no)'=>'Zobrazit pole předmětu (ano nebo ne)','My support requests'=>'Moje požadavky na podporu','Chat button'=>'Tlačítko chatu','Chat with us'=>'Chatujte s námi','Support'=>'Podpora','Thank you. Your request is ticket #%d. We have emailed you a link to follow it.'=>'Děkujeme. Vaše žádost má číslo #%d. Odeslali jsme vám e-mailem odkaz pro její sledování.','Your reply has been sent.'=>'Vaše odpověď byla odeslána.','If there is a request under that address, we have emailed you a new link.'=>'Pokud je na této adrese evidován požadavek, odeslali jsme vám nový odkaz e-mailem.','Something went wrong. Please check the form and try again.'=>'Něco se pokazilo. Zkontrolujte prosím formulář a zkuste to znovu.','Your message could not be sent.'=>'Vaši zprávu se nepodařilo odeslat.','You are sending messages too quickly. Please wait a little and try again.'=>'Odesíláte zprávy příliš rychle. Počkejte chvíli a zkuste to znovu.','Please agree to the privacy notice to send your request.'=>'Pro odeslání vašeho požadavku prosím vyjádřete souhlas s oznámením o ochraně osobních údajů.','Please complete the check to show you are not a robot.'=>'Dokončete prosím ověření, abyste prokázali, že nejste robot.','Sign in to see your support requests.'=>'Přihlaste se a zobrazte své požadavky na podporu.','Your name'=>'Vaše jméno','Your email'=>'Váš e-mail','Subject'=>'Předmět','Which order is this about?'=>'Tohle se týká které objednávky?','Not about an order'=>'Nejde o objednávku','How can we help?'=>'Jak vám můžeme pomoci?','Privacy policy'=>'Zásady ochrany osobních údajů','Send request'=>'Odeslat požadavek','All requests'=>'Všechny požadavky','Your support requests'=>'Vaše požadavky na podporu','You have no support requests yet.'=>'Zatím nemáte žádné žádosti o podporu.','Updated'=>'Aktualizováno','New request'=>'Nová žádost','This link has expired. Enter your email address and we will send you a new one.'=>'Tento odkaz vypršel. Zadejte svou e-mailovou adresu a my vám pošleme nový.','This link is not valid. Enter your email address and we will send you a link to your requests.'=>'Tento odkaz není platný. Zadejte svou e-mailovou adresu a my vám pošleme odkaz na vaše požadavky.','Email me a new link'=>'Pošlete mi e-mailem nový odkaz','Request #%1$d: %2$s'=>'Žádost č. %1$d: %2$s','Status:'=>'Stav:','Your reply'=>'Vaše odpověď','Send reply'=>'Odeslat odpověď','You'=>'Vy','Submit a ticket'=>'Odeslat tiket','Add to Menu'=>'Přidat do nabídky','Create the support page on the Zinn® Chat setup screen to add a "Submit a ticket" link.'=>'Vytvořte stránku podpory na obrazovce nastavení Zinn® Chat pro přidání odkazu „Odeslat požadavek“.','[#%1$d] We have your request: %2$s'=>'[#%1$d] Evidujeme váš požadavek: %2$s','Thank you for contacting us. We have received your request and will reply as soon as we can.'=>'Děkujeme, že jste nás kontaktovali. Vaši žádost jsme přijali a odpovíme vám, jakmile to bude možné.','View your request'=>'Zobrazit vaši žádost','[#%1$d] New ticket: %2$s'=>'[#%1$d] Nový tiket: %2$s','Open the ticket'=>'Otevřít tiket','[#%1$d] New reply: %2$s'=>'[#%1$d] Nová odpověď: %2$s','You can reply on the page below.'=>'Odpovědět můžete na níže uvedené stránce.','View and reply'=>'Zobrazit a odpovědět','[#%1$d] Customer replied: %2$s'=>'[#%1$d] Zákazník odpověděl: %2$s','A visitor is waiting in chat #%d'=>'Návštěvník čeká v chatu č. %d','A visitor asked to talk to a person and is waiting for an answer.'=>'Návštěvník požádal o rozhovor s osobou a čeká na odpověď.','Answer now'=>'Odpovědět nyní','Your chat with %s'=>'Váš chat s %s','[#%d] Your link to your request'=>'[#%d] Odkaz na váš požadavek','Here is a new link to your request. The old one no longer works.'=>'Zde je nový odkaz na vaši žádost. Starý již nefunguje.','From: %s'=>'Od: %s','a visitor'=>'návštěvník','Zinn® Chat chats and support tickets'=>'Konverzace a tikety podpory Zinn® Chat','Chats'=>'Chaty','Started'=>'Spuštěno','Name'=>'Název','Email'=>'E-mail','Page'=>'Stránka','Messages'=>'Zprávy','Support tickets'=>'Podpůrné tikety','Ticket'=>'Ticket','Opened'=>'Otevřeno','When you use the chat or submit a support request, we store your messages, the name and email address you give us, the page you were on and a coded form of your IP address, so that we can answer you and keep a record of your request.'=>'Když použijete chat nebo odešlete požadavek na podporu, uložíme vaše zprávy, jméno a e-mailovou adresu, kterou nám poskytnete, stránku, na které jste se nacházeli, a zakódovanou podobu vaší IP adresy, abychom vám mohli odpovědět a uchovat záznam o vašem požadavku.','If our AI assistant answers you, your message and passages from this website are sent to the AI provider we use to produce the answer.'=>'Pokud vám náš AI asistent odpoví, vaše zpráva a pasáže z tohoto webu budou odeslány poskytovateli AI, kterého používáme k vytvoření odpovědi.','This chat has ended.'=>'Tento chat skončil.','The chat is not available right now.'=>'Chat není v tuto chvíli k dispozici.','Please type a message.'=>'Zadejte prosím zprávu.','Please agree to the privacy notice to start the chat.'=>'Pro zahájení chatu prosím odsouhlaste zásady ochrany osobních údajů.','You have started too many chats today. Please try again tomorrow or send us a ticket.'=>'Dnes jste zahájili příliš mnoho chatů. Zkuste to prosím znovu zítra nebo nám pošlete tiket.','The chat could not be started. Please try again.'=>'Chat se nepodařilo spustit. Zkuste to prosím znovu.','Nobody can answer in chat right now. Leave your email address and we will reply by email.'=>'Nikdo teď nemůže v chatu odpovědět. Zanechte svou e-mailovou adresu a my vám odpovíme e-mailem.','The assistant cannot answer right now. You can ask for a person or leave us a message.'=>'Asistent nyní nemůže odpovědět. Můžete požádat o živého operátora nebo nám zanechat zprávu.','We are putting you through to a person. Please stay on this page.'=>'Připojujeme vás k živému operátorovi. Zůstaňte prosím na této stránce.','Tickets are not available right now.'=>'Lístky nejsou v tuto chvíli k dispozici.','Visitor'=>'Návštěvník','Team'=>'Tým','Chat so far:'=>'Dosavadní konverzace:','Thank you. Your request is ticket #%d and we will reply by email.'=>'Děkujeme. Vaše žádost má číslo #%d a odpovíme vám e-mailem.','Please enter a valid email address.'=>'Zadejte prosím platnou e-mailovou adresu.','This link is not valid.'=>'Tento odkaz není platný.','This link has expired. We can email you a new one.'=>'Tento odkaz vypršel. Můžeme vám poslat nový e-mailem.','You cannot see this ticket.'=>'Tento tiket nemůžete zobrazit.','Hi! Ask me anything about this site. I answer from its own pages, and I can put you through to a person.'=>'Dobrý den! Zeptejte se mě na cokoli ohledně tohoto webu. Odpovídám na základě jeho stránek a mohu vás přepojit na živou osobu.','Hi! How can we help? Send us a message and we will get back to you.'=>'Ahoj! Jak vám můžeme pomoci? Napište nám zprávu a my se vám ozveme.','Nobody is online right now. Leave your question and email address and we will reply by email.'=>'Nikdo je právě teď online. Zanechte svou otázku a e-mailovou adresu a my vám odpovíme e-mailem.','We keep this conversation so we can answer you.'=>'Tuto konverzaci uchováváme, abychom vám mohli odpovědět.','Please enter a valid email address so we can reply.'=>'Zadejte platnou e-mailovou adresu, abychom vám mohli odpovědět.','Please describe what you need help with.'=>'Popište prosím, s čím potřebujete pomoci.','The ticket could not be saved. Please try again.'=>'Požadavek se nepodařilo uložit. Zkuste to prosím znovu.','That ticket does not exist.'=>'Tento tiket neexistuje.','The reply is empty.'=>'Odpověď je prázdná.','Waiting for customer'=>'Čeká se na zákazníka','Solved'=>'Vyřešeno','Closed'=>'Uzavřeno','Open chat'=>'Otevřít chat','I agree'=>'Souhlasím','Type your message…'=>'Napište svou zprávę…','Send'=>'Odeslat','Close chat'=>'Zavřít chat','Minimise'=>'Minimalizovat','Talk to a person'=>'Promluvit si s člověkem','Leave a message'=>'Zanechat zprávu','Your message'=>'Vaše zpráva','Send message'=>'Odeslat zprávu','Cancel'=>'Zrušit','Support team'=>'Tým podpory','is typing…'=>'píše…','Looking this up…'=>'Vyhledává se…','Sources'=>'Zdroje','Was this helpful?'=>'Byla tato nápověda užitečná?','Yes'=>'Ano','No'=>'Ne','Thank you for your feedback.'=>'Děkujeme za vaši zpětnou vazbu.','Email me this chat'=>'Poslat mi tento chat e-mailem','Sent.'=>'Odesláno.','End chat'=>'Ukončit chat','The chat has ended.'=>'Chat skončil.','Something went wrong. Please try again.'=>'Něco se pokazilo. Zkuste to prosím znovu.','Powered by Zinn® Chat'=>'Vytvořeno pomocí Zinn® Chat','Start a new chat'=>'Zahájit nový chat','Get help with this order'=>'Získat pomoc s touto objednávkou','Order #%1$s (%2$s)'=>'Objednávka č. %1$s (%2$s)','Hosting customer? Get %1$d%% off %2$s'=>'Jste zákazník hostingu? Získejte slevu %1$d%% na %2$s','As a Zinn Digital® hosting customer you get a personal code for %d%% off your first payment